/* Flattens the three modules into one file that can be pasted straight into
   the Cloudflare dashboard editor, for deploying without a terminal:
     node worker/scripts/bundle.js
   Writes worker/dist/nixora-forms.js. The modules stay the source of truth —
   rebuild after editing them. */

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const src = join(here, '..', 'src');
const out = join(here, '..', 'dist');

// Order matters: each file may only use what the ones above it defined.
const ORDER = ['email.js', 'forms.js', 'index.js'];

const HEADER = `/* ==========================================================================
   Nixora Services LLC — form endpoint (single-file build).

   Generated by worker/scripts/bundle.js from src/email.js, src/forms.js and
   src/index.js. Do not edit this file: edit those and rebuild, or the next
   build will overwrite whatever was changed here.

   This is the file to paste into the Cloudflare dashboard editor when
   deploying without a terminal. See worker/README.md.
   ========================================================================== */

`;

const flatten = (name) => {
  const body = readFileSync(join(src, name), 'utf8');
  return body
    // The modules are concatenated, so cross-file imports have nothing left
    // to resolve and every name is already in scope.
    .replace(/^import\s+\{[^}]*\}\s+from\s+'[^']*';\s*$/gm, '')
    .replace(/^export\s+(function|const|class)\s/gm, '$1 ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
};

const bundle = HEADER + ORDER.map(flatten).join('\n\n') + '\n';

mkdirSync(out, { recursive: true });
writeFileSync(join(out, 'nixora-forms.js'), bundle);
console.log('worker/dist/nixora-forms.js  —', bundle.split('\n').length, 'lines,',
  (Buffer.byteLength(bundle) / 1024).toFixed(1) + ' KB');
